// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _setVal, uint256 _am, address caller) public {
        // Bound _setVal to a reasonable range
        _setVal = bound(_setVal, 0, 1e30);
        // Bound _am to a reasonable range
        _am = bound(_am, 0, 1e30);

        // Call SetMinSum with a specific value
        c.SetMinSum(_setVal);

        // Optionally call Collect with some amount (may revert, but we care about MinSum after the call)
        // Use try/catch to handle potential revert
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _am));

        // After the call, MinSum must equal the value set by SetMinSum
        uint256 expectedMinSum = _setVal;
        assertTrue(c.MinSum() == expectedMinSum, "MinSum should equal the value set by SetMinSum");
    }
}

